<?php

declare(strict_types=1);

namespace Architex\Tests\Integration\Environment;

use Architex\Platform\Environment\RegulatoryCaseException;
use Architex\Platform\Environment\RegulatoryCaseService;
use Architex\Platform\Identity\Identifier;
use Architex\Tests\Support\MariaDbTestCase;

final class RegulatoryCaseServiceTest extends MariaDbTestCase
{
    public function testEnvironmentalAndHeritageEvidenceRequiresProfessionalDetermination():void
    {
        [$o,$u,$p]=$this->seed('ENV1','environmental_practitioner');$service=new RegulatoryCaseService($this->pdo);
        $case=$service->create($o,$u,'owner',['projectId'=>$p,'caseNumber'=>'ENV-2026-01','caseType'=>'environmental','title'=>'Mixed-use environmental screening','authorityName'=>'DFFE / competent authority','responsibleRole'=>'environmental_practitioner','sourceBasis'=>[['title'=>'DFFE National Web-Based Environmental Screening Tool','url'=>'https://www.dffe.gov.za/egis','retrievedAt'=>'2026-08-28']]]);self::assertSame('draft',$case['status']);self::assertFalse($case['authorityDecisionClaimed']);
        $screening=$service->addEvidence($o,$u,'owner',$case['id'],1,['evidenceType'=>'screening_report','title'=>'DFFE screening report','status'=>'complete','externalReference'=>'SCREEN-01','sourceUrl'=>'https://screening.environment.gov.za/screeningtool','observedAt'=>'2026-08-28','payload'=>['sensitivities'=>['aquatic'=>'high','terrestrial'=>'medium'],'generatedOutsideArchitex'=>true]]);self::assertSame(2,$screening['caseVersion']);try{$service->addEvidence($o,$u,'owner',$case['id'],1,['evidenceType'=>'listed_activity_review','title'=>'Stale write','status'=>'complete','externalReference'=>'STALE-01','sourceUrl'=>'https://example.test/stale','observedAt'=>'2026-08-28','payload'=>[]]);self::fail('Stale writes must fail closed.');}catch(RegulatoryCaseException$e){self::assertSame('regulatory_version_conflict',$e->reason);}
        $service->addEvidence($o,$u,'owner',$case['id'],2,['evidenceType'=>'site_sensitivity_verification','title'=>'Site sensitivity verification','status'=>'complete','externalReference'=>'SSV-01','sourceUrl'=>'https://example.test/controlled-evidence/ssv-01','observedAt'=>'2026-08-28','payload'=>['verifiedBy'=>'Appointed EAP','screeningDisputes'=>[]]]);
        try{$service->determine($o,$u,'owner',$case['id'],3,false,'environmental_practitioner','basic_assessment','Exact screening and site evidence reviewed.','EA-ROUTE-01');self::fail('Human confirmation is required.');}catch(RegulatoryCaseException$e){self::assertSame('regulatory_determination_confirmation_required',$e->reason);}
        $reviewer=$this->reviewer($o,$u);$this->pdo->prepare("UPDATE verification_records SET grade='self_declared',reviewed_by=NULL,reviewed_at=NULL WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u)")->execute(['o'=>$o,'u'=>$u]);try{$service->determine($o,$u,'owner',$case['id'],3,true,'environmental_practitioner','basic_assessment','Exact screening report and site sensitivity verification reviewed.','EA-ROUTE-01');self::fail('Unverified professional authority must fail closed.');}catch(RegulatoryCaseException$e){self::assertSame('regulatory_determination_role_denied',$e->reason);}$this->pdo->prepare("UPDATE verification_records SET grade='manually_reviewed',reviewed_by=UNHEX(:reviewer),reviewed_at=UTC_TIMESTAMP(6) WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u)")->execute(['reviewer'=>$reviewer,'o'=>$o,'u'=>$u]);$this->pdo->prepare("UPDATE professional_profiles SET profession='architect' WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u)")->execute(['o'=>$o,'u'=>$u]);try{$service->determine($o,$u,'owner',$case['id'],3,true,'environmental_practitioner','basic_assessment','Exact screening report and site sensitivity verification reviewed.','EA-ROUTE-01');self::fail('A registration for another profession must fail closed.');}catch(RegulatoryCaseException$e){self::assertSame('regulatory_determination_role_denied',$e->reason);}$this->pdo->prepare("UPDATE professional_profiles SET profession='environmental_practitioner' WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u)")->execute(['o'=>$o,'u'=>$u]);
        $determined=$service->determine($o,$u,'owner',$case['id'],3,true,'environmental_practitioner','basic_assessment','Exact screening report and site sensitivity verification reviewed by the responsible practitioner.','EA-ROUTE-01');self::assertSame('determined',$determined['status']);self::assertSame('basic_assessment',$determined['determinationRoute']);self::assertMatchesRegularExpression('/\A[a-f0-9]{64}\z/',$determined['snapshotSha256']);self::assertFalse($determined['authorityDecisionClaimed']);self::assertNotNull($determined['projectRecordId']);

        [$o2,$u2,$p2]=$this->seed('HER1','heritage_practitioner');$heritage=$service->create($o2,$u2,'owner',['projectId'=>$p2,'caseNumber'=>'HER-2026-01','caseType'=>'heritage','title'=>'Section 38 heritage screening','authorityName'=>'SAHRA / responsible heritage authority','responsibleRole'=>'heritage_practitioner','sourceBasis'=>[['title'=>'SAHRA Section 38 minimum standards','url'=>'https://www.sahra.org.za/minimum-standards-for-heritage-reports-for-public-review/','retrievedAt'=>'2026-08-28']]]);$service->addEvidence($o2,$u2,'owner',$heritage['id'],1,['evidenceType'=>'heritage_nid','title'=>'Notification of Intent to Develop','status'=>'submitted_externally','externalReference'=>'SAHRIS-NID-01','sourceUrl'=>'https://www.sahra.org.za/','observedAt'=>'2026-08-28','payload'=>['submittedByHuman'=>true]]);$hia=$service->addEvidence($o2,$u2,'owner',$heritage['id'],2,['evidenceType'=>'heritage_impact_assessment','title'=>'Draft HIA','status'=>'complete','externalReference'=>'HIA-P01','sourceUrl'=>'https://example.test/controlled-evidence/hia-p01','observedAt'=>'2026-08-28','payload'=>['publicReviewRequired'=>true]]);self::assertSame(3,$hia['caseVersion']);self::assertCount(2,$service->get($o2,$u2,$heritage['id'])['evidence']);
    }

    public function testTenantIsolationAndEvidenceGateFailClosed():void
    {
        [$o,$u,$p]=$this->seed('ENV2','environmental_practitioner');[$other,$otherUser]=$this->seed('ENV3','environmental_practitioner');$service=new RegulatoryCaseService($this->pdo);$case=$service->create($o,$u,'owner',['projectId'=>$p,'caseNumber'=>'ENV-2026-02','caseType'=>'environmental','title'=>'Protected-area screening','authorityName'=>'Competent authority','responsibleRole'=>'environmental_practitioner','sourceBasis'=>[['title'=>'DFFE EGIS','url'=>'https://www.dffe.gov.za/egis','retrievedAt'=>'2026-08-28']]]);
        try{$service->determine($o,$u,'owner',$case['id'],1,true,'environmental_practitioner','no_ea_indicated','No listed route indicated.','ROUTE-02');self::fail('Screening evidence is required.');}catch(RegulatoryCaseException$e){self::assertSame('regulatory_determination_evidence_incomplete',$e->reason);}try{$service->get($other,$otherUser,$case['id']);self::fail('Cross tenant read must fail.');}catch(RegulatoryCaseException$e){self::assertSame('regulatory_case_not_found',$e->reason);}
    }

    private function reviewer(string$o,string$u):string{$s=$this->pdo->prepare("SELECT LOWER(HEX(reviewed_by)) FROM verification_records WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) LIMIT 1");$s->execute(['o'=>$o,'u'=>$u]);$reviewer=$s->fetchColumn();if(!is_string($reviewer))throw new \RuntimeException('Reviewer was not seeded.');return$reviewer;}
    /** @return array{string,string,string} */private function seed(string$code,string$role):array{$o=Identifier::generate();$u=Identifier::generate();$reviewer=Identifier::generate();$p=Identifier::generate();$this->pdo->prepare("INSERT INTO users(id,email,password_hash,status,email_verified_at) VALUES(UNHEX(:id),:email,'hash','active',UTC_TIMESTAMP(6)),(UNHEX(:reviewer),:reviewer_email,'hash','active',UTC_TIMESTAMP(6))")->execute(['id'=>$u,'email'=>strtolower($code).'@regulatory.test','reviewer'=>$reviewer,'reviewer_email'=>strtolower($code).'-reviewer@regulatory.test']);$this->pdo->prepare("INSERT INTO organisations(id,name,slug,status) VALUES(UNHEX(:id),:name,:slug,'active')")->execute(['id'=>$o,'name'=>$code,'slug'=>strtolower($code).'-'.substr($o,0,8)]);$this->pdo->prepare("INSERT INTO organisation_memberships(id,organisation_id,user_id,role,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),'owner','active')")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u]);$this->pdo->prepare("INSERT INTO professional_profiles(id,organisation_id,user_id,display_name,profession,bio,service_areas,directory_visible) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),:name,:role,'Test profile',JSON_ARRAY('Gauteng'),0)")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u,'name'=>$code.' practitioner','role'=>$role]);$this->pdo->prepare("INSERT INTO verification_records(id,organisation_id,user_id,kind,grade,registration_body,registration_number,popia_consent_at,processing_purpose,retention_until,reviewed_by,reviewed_at) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),'professional_registration','manually_reviewed','Test registration body',:number,UTC_TIMESTAMP(6),'Regulatory determination test',DATE_ADD(UTC_DATE(),INTERVAL 1 YEAR),UNHEX(:reviewer),UTC_TIMESTAMP(6))")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u,'number'=>$code.'-REG','reviewer'=>$reviewer]);$this->pdo->prepare("INSERT INTO projects(id,organisation_id,project_code,project_name,client_name,municipality,property_reference,property_use,land_use_notes,lead_professional_role,current_phase,created_by) VALUES(UNHEX(:id),UNHEX(:o),:code,:name,'Client','Tshwane','Erf 60','Mixed use','Sensitive-site review',:role,'feasibility',UNHEX(:u))")->execute(['id'=>$p,'o'=>$o,'code'=>$code,'name'=>"$code regulatory",'role'=>$role,'u'=>$u]);return[$o,$u,$p];}
}
